"""Fixed-width EXPORT_ACCT record formatter."""

from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
from typing import Any

__all__ = ["format_account"]

_RECORD_LENGTH = 77


def _value(row: dict, key: str) -> Any:
    value = row.get(key, "")
    return "" if value is None else value


def _fixed(value: Any, width: int) -> str:
    text = str(value)
    return text[:width].ljust(width)


def _annual_revenue_cents(value: Any) -> str:
    if value == "":
        value = 0

    try:
        cents = (Decimal(str(value)) * Decimal(100)).to_integral_value(
            rounding=ROUND_HALF_UP
        )
    except (InvalidOperation, ValueError) as exc:
        raise ValueError("ANN_REV must be a finite decimal value") from exc

    if not cents.is_finite():
        raise ValueError("ANN_REV must be a finite decimal value")

    rendered = str(int(cents)).zfill(15)
    if len(rendered) > 15:
        raise ValueError("ANN_REV cents exceed the 15-character field")
    return rendered


def format_account(row: dict) -> str:
    """Build one 77-character legacy EXPORT_ACCT record."""
    cred_hold = _value(row, "CRED_HOLD")
    if cred_hold == "":
        cred_hold = "N"
    else:
        cred_hold = str(cred_hold)

    create_dt = _value(row, "CREATE_DT")
    if create_dt == "":
        create_dt = "00000000"
    else:
        create_dt = str(create_dt)

    if len(cred_hold) != 1:
        raise ValueError("CRED_HOLD must be exactly one character")
    if len(create_dt) != 8:
        raise ValueError("CREATE_DT must be exactly eight characters")

    record = (
        _fixed(_value(row, "ACCT_ID"), 10)
        + _fixed(_value(row, "ACCT_NM"), 40)
        + _fixed(_value(row, "REGION_CD"), 3)
        + _annual_revenue_cents(_value(row, "ANN_REV"))
        + cred_hold
        + create_dt
    )

    if len(record) != _RECORD_LENGTH:
        raise AssertionError("EXPORT_ACCT record length invariant violated")

    return record
